func (m *membership) isPromoteObserver(cc pb.ConfigChange) bool {
	if cc.Type == pb.AddNode {
		oa, ok := m.members.Observers[cc.NodeID]
		return ok && addressEqual(oa, cc.Address)
	}
	return false
}

